class UserProvisioner:
    def __init__(self, send_email):
        self.send_email = send_email

    def create(self, username, raw_password):
        user = User.objects.create(username=username, password=make_password(raw_password))
        if self.send_email:
            user.email_user('welcome', 'Set your password from the portal.')
        return {'id': user.id, 'username': user.username, 'email_sent': self.send_email}


class CreateUserView(APIView):
    def post(self, request):
        provisioner = UserProvisioner(send_email=True)
        body = provisioner.create(
            username=request.data['username'],
            raw_password=request.data['password'],
        )
        return Response(body, status=201)

from datetime import timedelta

from django.utils import timezone
from rest_framework.response import Response
from rest_framework.views import APIView

from app.masking import mask_email
from app.models import Order

LEGAL_HOLD_DAYS = 2190


class OrderRetentionJob:
    def __init__(self, days):
        self.days = days

    def receipt(self, batch, sample_email):
        return {'purged': len(batch), 'days': self.days, 'sample_customer': sample_email}

    def run(self):
        cutoff = timezone.now() - timedelta(days=self.days)
        batch = list(Order.objects.filter(created_at__lt=cutoff, refunded=True)[:500])
        if not batch:
            return self.receipt(batch=[], sample_email=None)
        note = self.receipt(batch=batch, sample_email=mask_email(batch[0].customer_email))
        Order.objects.filter(id__in=[order.id for order in batch]).delete()
        return note


class OrderRetentionView(APIView):
    def post(self, request):
        return Response(OrderRetentionJob(days=LEGAL_HOLD_DAYS).run())

